css:
/* Graphite neutrals, one green accent, hairline borders. Colour inside the
   field and maps is content, not chrome. */
:root{
  --page:#fafafa; --card:#ffffff; --raised:#f4f4f5;
  --ink:#171717; --ink-2:#525252; --ink-3:#737373;
  --hair:rgba(23,23,23,.09); --hair-strong:rgba(23,23,23,.16);
  --accent:#15803d; --on-accent:#ffffff; --neg:#c62828;
  --primary-bg:#171717; --primary-fg:#ffffff;
  --shadow-sm:0 1px 2px rgba(0,0,0,.05);
  --ease:cubic-bezier(.22,1,.36,1);
  /* field */
  --turf:#3f7f4c; --turf-ink:#f3f7f2; --rope:#ffffff; --ring:rgba(255,255,255,.55); --pitch:#d8c897;
  --chip:#ffffff; --chip-edge:#12251a; --brass:#f5c542;
  --six:#f5c542; --four:#ffffff; --out:#ffb3a7; --run:#10261a;
  /* maps */
  --map-surface:#ffffff; --map-band-a:#f4f4f5; --map-band-b:#e9e9eb; --map-line:#a3a3a8; --map-ink:#525252;
  --map-dot:#171717; --map-latest:#15803d; --map-stump:#8a8a90;
}
@media (prefers-color-scheme:dark){
  :root{
    --page:#141415; --card:#19191b; --raised:#232325;
    --ink:#ededed; --ink-2:#a1a1a6; --ink-3:#85858b;
    --hair:rgba(237,237,237,.09); --hair-strong:rgba(237,237,237,.18);
    --accent:#4cc38a; --on-accent:#0c1f15; --neg:#f0736f;
    --primary-bg:#ededed; --primary-fg:#141415;
    --shadow-sm:none;
    --turf:#2f6239; --pitch:#b3a374; --chip-edge:#0b160f;
    --map-surface:#19191b; --map-band-a:#232325; --map-band-b:#2b2b2e; --map-line:#5c5c62; --map-ink:#a1a1a6;
    --map-dot:#ededed; --map-latest:#4cc38a; --map-stump:#85858b;
  }
}
*{box-sizing:border-box;}
[hidden]{display:none !important;}
html,body{height:100%;margin:0;}
body{background:var(--page);color:var(--ink);font:400 15px/22px 'Geist',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums;}
button,select,input{font:inherit;color:inherit;}
.mono{font-family:'Geist Mono',ui-monospace,SFMono-Regular,Menlo,monospace;}
#app{display:flex;flex-direction:column;height:100%;max-width:920px;margin:0 auto;}

.topbar{height:56px;flex:0 0 auto;padding:0 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;
  border-bottom:1px solid var(--hair);}
.topbar h1{margin:0;font-size:16px;line-height:1;font-weight:600;}
.topbar .score{font-family:'Geist Mono',ui-monospace,monospace;font-size:13px;color:var(--ink-2);white-space:nowrap;}
.topbar .score b{font-weight:500;color:var(--ink);}

main{flex:1;overflow-y:auto;padding:20px 20px 96px;}
.view{display:none;} .view.on{display:block;}
.card{background:var(--card);border:1px solid var(--hair);border-radius:12px;padding:20px;margin-bottom:16px;}
.label{font-size:13px;line-height:20px;color:var(--ink-2);}
.card > .label{font-weight:500;color:var(--ink);font-size:14px;}
.muted{color:var(--ink-2);font-size:13px;line-height:20px;}

.seg{display:flex;background:var(--raised);border-radius:10px;padding:4px;gap:4px;}
.seg button{flex:1;border:none;background:transparent;padding:0 8px;border-radius:7px;font-size:14px;font-weight:500;
  color:var(--ink-2);cursor:pointer;min-height:36px;transition:background-color .15s var(--ease),color .15s var(--ease);}
.seg button.on{background:var(--card);color:var(--ink);box-shadow:var(--shadow-sm);}
.btn{border:1px solid var(--hair-strong);background:var(--card);border-radius:8px;padding:0 16px;font-size:14px;font-weight:500;
  cursor:pointer;min-height:40px;transition:background-color .15s var(--ease),border-color .15s var(--ease);}
.btn:hover:not(:disabled){background:var(--raised);}
.btn.primary{background:var(--primary-bg);border-color:var(--primary-bg);color:var(--primary-fg);}
.btn.primary:hover:not(:disabled){background:var(--primary-bg);opacity:.9;}
.btn.warn{color:var(--neg);}
.btn:disabled{opacity:.45;cursor:default;}
button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}
.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap;}
.row .grow{flex:1;}

.stage{position:relative;margin:16px 0 12px;border-radius:12px;overflow:hidden;background:#0f0f10;aspect-ratio:16/9;}
.stage canvas{display:block;width:100%;height:100%;object-fit:contain;}
.stage .empty{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;
  color:#a1a1a6;text-align:center;padding:24px;gap:4px;font-size:14px;line-height:20px;}
.stage .empty b{font-size:16px;color:#ededed;font-weight:500;}
.pill{position:absolute;left:12px;top:12px;background:rgba(15,15,16,.78);color:#ededed;font-size:12px;line-height:16px;
  padding:6px 10px;border-radius:6px;display:flex;align-items:center;gap:8px;max-width:calc(100% - 24px);}
.dot{width:6px;height:6px;border-radius:50%;background:#85858b;flex:0 0 auto;}
.dot.live{background:#4cc38a;} .dot.busy{background:#f5c542;} .dot.bad{background:#f0736f;}

.result .head{font-size:30px;line-height:1.15;font-weight:500;letter-spacing:-.01em;margin-top:4px;}
.result .head.out{color:var(--neg);}
.result .sub{margin-top:4px;font-size:14px;line-height:20px;color:var(--ink-2);}
/* stat cells divided by hairlines rather than boxed */
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));
  border:1px solid var(--hair);border-radius:10px;overflow:hidden;margin-top:16px;}
.tile{padding:12px 16px 14px;min-width:0;border-right:1px solid var(--hair);border-bottom:1px solid var(--hair);margin:0 -1px -1px 0;}
.card.flush{padding:0;overflow:hidden;} .card.flush .tiles{margin:0;border:none;border-radius:0;} .card.flush > p{padding:20px;}
.tile .v{font-size:26px;line-height:32px;font-weight:500;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.tile .v.word{font-size:18px;line-height:32px;}
.tile .v small{font-family:'Geist Mono',ui-monospace,monospace;font-size:12px;font-weight:400;color:var(--ink-3);margin-left:4px;}
.tile .n{font-size:12px;line-height:16px;color:var(--ink-3);margin-top:2px;}
.truth{margin-top:12px;font-size:12px;line-height:16px;color:var(--ink-3);font-family:'Geist Mono',ui-monospace,monospace;}

.fieldwrap{width:100%;max-width:560px;margin:0 auto;aspect-ratio:1/1;}
.fieldwrap canvas{width:100%;height:100%;display:block;touch-action:none;}
.fieldwrap.mini{max-width:320px;margin-top:8px;}
.fieldwrap.mini canvas{touch-action:auto;}
.legend{display:flex;gap:16px;flex-wrap:wrap;justify-content:center;font-size:12px;line-height:16px;color:var(--ink-2);margin-top:8px;}
.legend i{display:inline-block;width:14px;height:4px;border-radius:2px;vertical-align:middle;margin-right:6px;
  box-shadow:0 0 0 1px var(--hair-strong);}

.maps{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:12px;position:relative;}
.maps figure{margin:0;min-width:0;}
.maps figcaption{font-size:13px;line-height:20px;color:var(--ink-2);margin-bottom:8px;}
.mapwrap{height:300px;border:1px solid var(--hair);border-radius:10px;overflow:hidden;background:var(--map-surface);}
.mapwrap canvas{width:100%;height:100%;display:block;touch-action:pan-y;}
.maps .note{font-size:12px;line-height:16px;color:var(--ink-3);margin:8px 0 0;}
.key{display:inline-block;width:9px;height:9px;border-radius:50%;vertical-align:-1px;margin:0 4px 0 2px;border:2px solid var(--map-dot);}
.key.fill{background:var(--map-dot);} .key.latest{background:var(--map-latest);border-color:var(--map-latest);}
.tip{position:absolute;z-index:5;background:var(--primary-bg);color:var(--primary-fg);font-size:12px;line-height:16px;
  padding:6px 8px;border-radius:6px;pointer-events:none;white-space:nowrap;}
@media (max-width:520px){ .maps{grid-template-columns:1fr;} }

.form{display:grid;grid-template-columns:1fr auto;gap:16px 16px;align-items:center;margin-top:12px;}
.form label{font-size:14px;line-height:20px;}
.form label small{display:block;color:var(--ink-3);font-size:12px;line-height:16px;}
.form input[type=number],.form select{width:120px;height:36px;padding:0 10px;border-radius:8px;border:1px solid var(--hair-strong);background:var(--card);}
select.btn{padding-right:8px;}
input[type=range]{width:100%;accent-color:var(--accent);margin:8px 0 0;}

table{width:100%;border-collapse:collapse;font-size:13px;line-height:20px;}
th{text-align:left;font-size:12px;font-weight:400;color:var(--ink-3);padding:8px;}
td{padding:8px;border-top:1px solid var(--hair);vertical-align:top;}
td b{font-weight:500;}
td.num,th.num{text-align:right;}
.tablewrap{overflow-x:auto;margin:8px -8px 0;}
ol.steps{margin:8px 0 0;padding-left:20px;font-size:14px;line-height:22px;color:var(--ink-2);}
ol.steps li{margin-bottom:8px;} ol.steps b{font-weight:500;color:var(--ink);}

nav.tabs{position:fixed;left:0;right:0;bottom:0;display:flex;justify-content:center;background:var(--card);
  border-top:1px solid var(--hair);padding:8px 12px calc(8px + env(safe-area-inset-bottom));z-index:10;}
nav.tabs div{display:flex;width:100%;max-width:440px;gap:4px;}
nav.tabs button{flex:1;border:none;background:transparent;font-size:12px;line-height:16px;font-weight:500;color:var(--ink-3);
  border-radius:8px;cursor:pointer;min-height:48px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;
  transition:background-color .15s var(--ease),color .15s var(--ease);}
nav.tabs button.on{color:var(--ink);background:var(--raised);}
nav.tabs svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;}
@media (max-width:719px){ #calInfo{flex-basis:100%;} main{padding:16px 16px 96px;} .topbar{padding:0 16px;} .card{padding:16px;} }
@media (min-width:720px){ .two{display:grid;grid-template-columns:1.3fr 1fr;gap:16px;align-items:start;} }

files.geometry.js:
// Small linear-algebra + single-camera geometry toolkit.
// World frame: origin at the base of the striker's middle stump, y runs down the
// pitch toward the bowler, z is up, x completes a right-handed frame (so +x is
// the off side for a right-hander). Units are metres and seconds.

export const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a, b) => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];
export const norm = (a) => Math.hypot(a[0], a[1], a[2]);
export const scale = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
export const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
export const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
export const unit = (a) => scale(a, 1 / (norm(a) || 1));

/** Solve A x = b by Gaussian elimination with partial pivoting. Returns null if singular. */
export function solve(A, b) {
  const n = b.length;
  const M = A.map((r, i) => [...r, b[i]]);
  for (let c = 0; c < n; c++) {
    let p = c;
    for (let r = c + 1; r < n; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
    if (Math.abs(M[p][c]) < 1e-13) return null;
    [M[c], M[p]] = [M[p], M[c]];
    for (let r = c + 1; r < n; r++) {
      const f = M[r][c] / M[c][c];
      if (f === 0) continue;
      for (let k = c; k <= n; k++) M[r][k] -= f * M[c][k];
    }
  }
  const x = new Array(n);
  for (let r = n - 1; r >= 0; r--) {
    let s = M[r][n];
    for (let k = r + 1; k < n; k++) s -= M[r][k] * x[k];
    x[r] = s / M[r][r];
  }
  return x;
}

/** Least squares for an over-determined system via the normal equations. */
export function lstsq(rows, rhs) {
  const n = rows[0].length;
  const ATA = Array.from({ length: n }, () => new Array(n).fill(0));
  const ATb = new Array(n).fill(0);
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    for (let a = 0; a < n; a++) {
      if (r[a] === 0) continue;
      ATb[a] += r[a] * rhs[i];
      for (let b = a; b < n; b++) ATA[a][b] += r[a] * r[b];
    }
  }
  let tr = 0;
  for (let a = 0; a < n; a++) {
    tr += ATA[a][a];
    for (let b = 0; b < a; b++) ATA[a][b] = ATA[b][a];
  }
  for (let a = 0; a < n; a++) ATA[a][a] += 1e-10 * tr + 1e-12;
  return solve(ATA, ATb);
}

/** Levenberg-Marquardt with a numeric Jacobian. resFn(x) -> residual array. */
export function levenberg(resFn, x0, { iters = 40 } = {}) {
  let x = x0.slice();
  let r = resFn(x);
  let cost = r.reduce((s, v) => s + v * v, 0);
  let lambda = 1e-3;
  const n = x.length;
  for (let it = 0; it < iters; it++) {
    const J = [];
    for (let j = 0; j < n; j++) {
      const h = 1e-6 * Math.max(1, Math.abs(x[j]));
      const xp = x.slice();
      xp[j] += h;
      const rp = resFn(xp);
      J.push(rp.map((v, i) => (v - r[i]) / h));
    }
    const JTJ = Array.from({ length: n }, () => new Array(n).fill(0));
    const JTr = new Array(n).fill(0);
    for (let a = 0; a < n; a++) {
      for (let i = 0; i < r.length; i++) JTr[a] += J[a][i] * r[i];
      for (let b = a; b < n; b++) {
        let s = 0;
        for (let i = 0; i < r.length; i++) s += J[a][i] * J[b][i];
        JTJ[a][b] = JTJ[b][a] = s;
      }
    }
    let improved = false;
    for (let tries = 0; tries < 8; tries++) {
      const A = JTJ.map((row, a) => row.map((v, b) => (a === b ? v * (1 + lambda) + 1e-12 : v)));
      const dx = solve(A, JTr.map((v) => -v));
      if (dx) {
        const xn = x.map((v, i) => v + dx[i]);
        const rn = resFn(xn);
        const cn = rn.reduce((s, v) => s + v * v, 0);
        if (cn < cost) {
          const gain = cost - cn;
          x = xn; r = rn; cost = cn;
          lambda = Math.max(lambda * 0.3, 1e-9);
          improved = gain > 1e-10 * (1 + cost);
          break;
        }
      }
      lambda *= 6;
    }
    if (!improved) break;
  }
  return { x, cost, r };
}

export function rodrigues(w) {
  const th = norm(w);
  if (th < 1e-12) return [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
  const [kx, ky, kz] = scale(w, 1 / th);
  const c = Math.cos(th), s = Math.sin(th), C = 1 - c;
  return [
    [c + kx * kx * C, kx * ky * C - kz * s, kx * kz * C + ky * s],
    [ky * kx * C + kz * s, c + ky * ky * C, ky * kz * C - kx * s],
    [kz * kx * C - ky * s, kz * ky * C + kx * s, c + kz * kz * C],
  ];
}

const matMul = (A, B) =>
  A.map((r) => [0, 1, 2].map((j) => r[0] * B[0][j] + r[1] * B[1][j] + r[2] * B[2][j]));

/** Build a pinhole camera. R rows are the camera axes (right, down, forward) in world coords. */
export function makeCam(f, cx, cy, R, t) {
  const P = [
    [f * R[0][0] + cx * R[2][0], f * R[0][1] + cx * R[2][1], f * R[0][2] + cx * R[2][2], f * t[0] + cx * t[2]],
    [f * R[1][0] + cy * R[2][0], f * R[1][1] + cy * R[2][1], f * R[1][2] + cy * R[2][2], f * t[1] + cy * t[2]],
    [R[2][0], R[2][1], R[2][2], t[2]],
  ];
  const C = [
    -(R[0][0] * t[0] + R[1][0] * t[1] + R[2][0] * t[2]),
    -(R[0][1] * t[0] + R[1][1] * t[1] + R[2][1] * t[2]),
    -(R[0][2] * t[0] + R[1][2] * t[1] + R[2][2] * t[2]),
  ];
  return { f, cx, cy, R, t, P, C };
}

export function lookAtCam(C, target, f, W, H) {
  const fwd = unit(sub(target, C));
  const right = unit(cross(fwd, [0, 0, 1]));
  const down = cross(fwd, right);
  const R = [right, down, fwd];
  const t = [-dot(right, C), -dot(down, C), -dot(fwd, C)];
  return makeCam(f, W / 2, H / 2, R, t);
}

/** Project a world point. Returns [u, v, depth]. */
export function project(cam, X) {
  const P = cam.P;
  const w = P[2][0] * X[0] + P[2][1] * X[1] + P[2][2] * X[2] + P[2][3];
  return [
    (P[0][0] * X[0] + P[0][1] * X[1] + P[0][2] * X[2] + P[0][3]) / w,
    (P[1][0] * X[0] + P[1][1] * X[1] + P[1][2] * X[2] + P[1][3]) / w,
    w,
  ];
}

/** Where the viewing ray through pixel (u,v) meets the horizontal plane z = z0. */
export function groundPoint(cam, u, v, z0 = 0) {
  const d = [(u - cam.cx) / cam.f, (v - cam.cy) / cam.f, 1];
  const R = cam.R;
  const dw = [
    R[0][0] * d[0] + R[1][0] * d[1] + R[2][0] * d[2],
    R[0][1] * d[0] + R[1][1] * d[1] + R[2][1] * d[2],
    R[0][2] * d[0] + R[1][2] * d[1] + R[2][2] * d[2],
  ];
  if (Math.abs(dw[2]) < 1e-9) return null;
  const s = (z0 - cam.C[2]) / dw[2];
  if (s <= 0) return null;
  return [cam.C[0] + s * dw[0], cam.C[1] + s * dw[1], z0];
}

function homography(world, img) {
  const rows = [], rhs = [];
  for (let i = 0; i < world.length; i++) {
    const [X, Y] = world[i], [u, v] = img[i];
    rows.push([X, Y, 1, 0, 0, 0, -u * X, -u * Y]); rhs.push(u);
    rows.push([0, 0, 0, X, Y, 1, -v * X, -v * Y]); rhs.push(v);
  }
  const h = world.length === 4 ? solve(rows, rhs) : lstsq(rows, rhs);
  return h && [[h[0], h[1], h[2]], [h[3], h[4], h[5]], [h[6], h[7], 1]];
}

function calibrateOnce(world, img, W, H) {
  const cx = W / 2, cy = H / 2;
  const pts = img.map(([u, v]) => [(u - cx) / W, (v - cy) / W]);
  const Hm = homography(world, pts);
  if (!Hm) return null;
  const a = [Hm[0][0], Hm[1][0], Hm[2][0]];
  const b = [Hm[0][1], Hm[1][1], Hm[2][1]];
  const c = [Hm[0][2], Hm[1][2], Hm[2][2]];
  // Focal length from the two constraints r1.r2 = 0 and |r1| = |r2|.
  const cands = [];
  const d1 = a[2] * b[2], n1 = -(a[0] * b[0] + a[1] * b[1]);
  const d2 = a[2] * a[2] - b[2] * b[2], n2 = -(a[0] * a[0] + a[1] * a[1] - b[0] * b[0] - b[1] * b[1]);
  if (Math.abs(d1) > 1e-12 && n1 / d1 > 0) cands.push([Math.abs(d1), Math.sqrt(n1 / d1)]);
  if (Math.abs(d2) > 1e-12 && n2 / d2 > 0) cands.push([Math.abs(d2), Math.sqrt(n2 / d2)]);
  cands.sort((p, q) => q[0] - p[0]);
  let f = cands.length ? cands[0][1] : 0.85;
  f = Math.min(4, Math.max(0.3, f));

  let r1 = [a[0] / f, a[1] / f, a[2]], r2 = [b[0] / f, b[1] / f, b[2]], t = [c[0] / f, c[1] / f, c[2]];
  let lam = 2 / (norm(r1) + norm(r2));
  if (t[2] < 0) lam = -lam;
  r1 = unit(scale(r1, lam));
  r2 = scale(r2, lam);
  r2 = unit(sub(r2, scale(r1, dot(r1, r2))));
  const r3 = cross(r1, r2);
  t = scale(t, lam);
  const R0 = [[r1[0], r2[0], r3[0]], [r1[1], r2[1], r3[1]], [r1[2], r2[2], r3[2]]];

  // Refine focal length + pose on reprojection error (R = rodrigues(delta) * R0).
  const build = (x) => makeCam(x[0], 0, 0, matMul(rodrigues([x[1], x[2], x[3]]), R0), [x[4], x[5], x[6]]);
  const res = (x) => {
    const cam = build(x), out = [];
    for (let i = 0; i < world.length; i++) {
      const p = project(cam, [world[i][0], world[i][1], 0]);
      out.push((p[0] - pts[i][0]) * W, (p[1] - pts[i][1]) * W);
