// Finds small fast-moving things in the video (three-frame differencing) and
// links them into ball tracks.

const CELL = 8;

export class Detector {
  constructor() { this.thr = 45; this.reset(); }
  reset() { this.frames = []; this.times = []; this.w = 0; this.h = 0; }

  /**
   * Feed one RGBA frame. Returns { t, blobs, noisy } for the PREVIOUS frame
   * (a pixel counts as moving only if it differs from both neighbours in time,
   * which removes the ghost a moving object leaves behind), or null while warming up.
   */
  process(img, t) {
    const w = img.width, h = img.height;
    if (w !== this.w || h !== this.h) {
      this.reset(); this.w = w; this.h = h;
      this.gw = Math.ceil(w / CELL); this.gh = Math.ceil(h / CELL);
      const n = this.gw * this.gh;
      this.cnt = new Uint16Array(n); this.sx = new Float32Array(n); this.sy = new Float32Array(n);
      this.label = new Uint8Array(n);
    }
    this.frames.push(img.data); this.times.push(t);
    if (this.frames.length < 3) return null;
    if (this.frames.length > 3) { this.frames.shift(); this.times.shift(); }
    const [a, b, c] = this.frames, thr = this.thr;
    const { cnt, sx, sy, label, gw, gh } = this;
    cnt.fill(0); sx.fill(0); sy.fill(0); label.fill(0);
    let hot = 0;
    for (let y = 0; y < h; y++) {
      const row = (y >> 3) * gw;
      let i = y * w * 4;
      for (let x = 0; x < w; x++, i += 4) {
        const d1 = Math.abs(b[i] - a[i]) + Math.abs(b[i + 1] - a[i + 1]) + Math.abs(b[i + 2] - a[i + 2]);
        if (d1 <= thr) continue;
        const d2 = Math.abs(b[i] - c[i]) + Math.abs(b[i + 1] - c[i + 1]) + Math.abs(b[i + 2] - c[i + 2]);
        if (d2 <= thr) continue;
        const ci = row + (x >> 3);
        cnt[ci]++; sx[ci] += x; sy[ci] += y; hot++;
      }
    }
    const out = { t: this.times[1], blobs: [], noisy: false, hot };
    if (hot > 0.06 * w * h) { out.noisy = true; return out; }      // camera shake / lighting change
    const maxDim = Math.max(24, 0.09 * w), stack = [];
    for (let s = 0; s < cnt.length; s++) {
      if (!cnt[s] || label[s]) continue;
      let n = 0, mx = 0, my = 0, x0 = gw, x1 = 0, y0 = gh, y1 = 0;
      stack.push(s); label[s] = 1;
      while (stack.length) {
        const q = stack.pop(), qx = q % gw, qy = (q - qx) / gw;
        n += cnt[q]; mx += sx[q]; my += sy[q];
        if (qx < x0) x0 = qx; if (qx > x1) x1 = qx; if (qy < y0) y0 = qy; if (qy > y1) y1 = qy;
        for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
          const nx = qx + dx, ny = qy + dy;
          if (nx < 0 || ny < 0 || nx >= gw || ny >= gh) continue;
          const ni = ny * gw + nx;
          if (cnt[ni] && !label[ni]) { label[ni] = 1; stack.push(ni); }
        }
      }
      const bw = (x1 - x0 + 1) * CELL, bh = (y1 - y0 + 1) * CELL;
      if (n < 3 || bw > maxDim || bh > maxDim) continue;
      out.blobs.push({ x: mx / n + 0.5, y: my / n + 0.5, n, bw, bh });
    }
    if (out.blobs.length > 40) { out.blobs.sort((p, q) => q.n - p.n); out.blobs.length = 40; }
    return out;
  }
}

const extent = (tr) => {
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (const p of tr.pts) { if (p.u < x0) x0 = p.u; if (p.u > x1) x1 = p.u; if (p.v < y0) y0 = p.v; if (p.v > y1) y1 = p.v; }
  return Math.hypot(x1 - x0, y1 - y0);
};

export class Tracker {
  constructor() { this.W = 1280; this.reset(); }
  reset() { this.tracks = []; this.closed = []; this.nextId = 1; }

  /** blobs in source-pixel coords. Returns { live, finished } where finished is null or a list of candidate observation lists. */
  update(blobs, t) {
    const W = this.W, gateMin = 0.03 * W;
    const used = new Array(blobs.length).fill(false);
    this.tracks.sort((a, b) => b.pts.length - a.pts.length);
    const keep = [];
    for (const tr of this.tracks) {
      const last = tr.pts[tr.pts.length - 1], dt = t - last.t;
      if (dt <= 0) { keep.push(tr); continue; }
      let px = last.u, py = last.v, gate;
      if (tr.pts.length >= 2) {
        px += tr.vx * dt; py += tr.vy * dt;
        gate = Math.max(gateMin, 0.9 * Math.hypot(tr.vx, tr.vy) * dt);
      } else gate = 12 * W * dt;
      let bi = -1, bd = gate;
      for (let i = 0; i < blobs.length; i++) {
        if (used[i]) continue;
        const d = Math.hypot(blobs[i].x - px, blobs[i].y - py);
        if (d < bd && Math.hypot(blobs[i].x - last.u, blobs[i].y - last.v) > 1.5) { bd = d; bi = i; }
      }
      if (bi >= 0) {
        used[bi] = true;
        const b = blobs[bi];
        tr.vx = (b.x - last.u) / dt; tr.vy = (b.y - last.v) / dt;
        tr.pts.push({ t, u: b.x, v: b.y });
        keep.push(tr);
      } else if (dt > (tr.pts.length >= 4 ? 0.11 : 0.05)) {
        if (tr.pts.length >= 6 && extent(tr) > 0.06 * W) this.closed.push(tr);
      } else keep.push(tr);
    }
    this.tracks = keep;
    for (let i = 0; i < blobs.length && this.tracks.length < 60; i++) {
      if (!used[i]) this.tracks.push({ id: this.nextId++, pts: [{ t, u: blobs[i].x, v: blobs[i].y }], vx: 0, vy: 0 });
    }

    let live = null;
    for (const tr of this.tracks) if (tr.pts.length >= 4 && (!live || tr.pts.length > live.pts.length)) live = tr;

    // Once things have gone quiet, hand back every candidate path (longest first).
    // The ball is often lost for a frame or two at the bat, so pieces are stitched.
    let finished = null;
    if (this.closed.length) {
      const end = (tr) => tr.pts[tr.pts.length - 1].t;
      const newest = Math.max(...this.closed.map(end)), oldest = Math.min(...this.closed.map(end));
      const busy = this.tracks.some((tr) => tr.pts.length >= 4 && extent(tr) > 0.03 * W);
      if ((!busy && t - newest > 0.6) || t - oldest > 6) {
        const pool = this.closed.concat(this.tracks.filter((tr) => tr.pts.length >= 4));
        const seeds = this.closed.slice().sort((a, b) => extent(b) - extent(a));
        const usedTr = new Set();
        finished = [];
        const near = (p, q) => Math.hypot(p.u - q.u, p.v - q.v) <= 0.3 * W;
        for (const seed of seeds) {
          if (usedTr.has(seed) || finished.length >= 4) continue;
          usedTr.add(seed);
          let chain = seed.pts.slice();
          for (let guard = 0; guard < 4; guard++) {
            const lp = chain[chain.length - 1], fp = chain[0];
            let pick = null, mode = '';
            for (const tr of pool) {
              if (usedTr.has(tr)) continue;
              const f = tr.pts[0], l = tr.pts[tr.pts.length - 1];
              let how = '';
              if (f.t > lp.t && f.t - lp.t <= 0.3 && near(f, lp)) how = 'after';
              else if (fp.t > l.t && fp.t - l.t <= 0.3 && near(fp, l)) how = 'before';
              else if (f.t > fp.t && f.t <= lp.t && lp.t - f.t <= 0.25 && l.t > lp.t) {
                // Branch: the path wandered onto the bat/batter while the ball itself
                // carried on as a new track. Take the branch if it travels further.
                let j = chain.length - 1;
                while (j > 0 && chain[j].t >= f.t) j--;
                const tailPts = { pts: chain.slice(j) };
                if (near(f, chain[j]) && extent(tr) > 1.5 * extent(tailPts)) how = 'branch';
              }
              else if (f.t < fp.t && l.t >= fp.t && l.t - fp.t <= 0.25) {
                // The same situation seen from the other side: this chain is the branch, tr is the trunk.
                let j = tr.pts.length - 1;
                while (j > 0 && tr.pts[j].t >= fp.t) j--;
                if (near(fp, tr.pts[j]) && extent(tr) > 0.06 * W) how = 'trunk';
              }
              if (how && (!pick || tr.pts.length > pick.pts.length)) { pick = tr; mode = how; }
            }
            if (!pick) break;
            usedTr.add(pick);
            if (mode === 'before') chain = pick.pts.concat(chain);
            else if (mode === 'after') chain = chain.concat(pick.pts);
            else if (mode === 'trunk') chain = pick.pts.filter((q) => q.t < chain[0].t).concat(chain);
            else chain = chain.filter((q) => q.t < pick.pts[0].t).concat(pick.pts);
          }
          finished.push(chain);
        }
        this.tracks = this.tracks.filter((tr) => !usedTr.has(tr));
        this.closed = [];
      }
    }
    return { live: live ? live.pts : null, finished };
  }
}

files.field.js:
// Field model: fielder placement, presets, position names and the top-down drawing.
// Positions are in the pitch frame (origin at the striker's stumps, +y toward the bowler).

const rad = Math.PI / 180;

// Presets for a right-hander as [angle, distance] from the striker:
// angle 0 = straight back past the bowler, positive = off side, 180 = behind the wicket.
export const PRESETS = {
  balanced: { label: 'Balanced', keeper: 9, f: [[165, 13], [88, 26], [55, 27], [18, 26], [-18, 26], [-58, 27], [-92, 24], [150, 55], [-150, 55]] },
  attacking: { label: 'Attacking (pace)', keeper: 10, f: [[168, 12], [162, 13.5], [156, 15], [128, 15], [90, 25], [55, 27], [18, 27], [-20, 27], [-150, 55]] },
  defensive: { label: 'Defensive (death overs)', keeper: 9, f: [[150, 58], [88, 62], [58, 62], [18, 64], [-18, 64], [-58, 63], [-95, 60], [-140, 28], [45, 27]] },
  spin: { label: 'Spin', keeper: 2.5, f: [[165, 4.5], [-70, 4], [90, 24], [55, 26], [20, 25], [-20, 25], [-60, 26], [-95, 58], [-15, 62]] },
};

export function clampInside(f, L, boundary) {
  const cy = L / 2, d = Math.hypot(f.x, f.y - cy), max = boundary - 1.5;
  if (d > max) { f.x *= max / d; f.y = cy + (f.y - cy) * max / d; }
}

export function makeField(presetKey, hand, L, boundary) {
  const p = PRESETS[presetKey] || PRESETS.balanced, off = hand === 'L' ? -1 : 1;
  const fielders = [
    { id: 'wk', role: 'keeper', x: 0, y: -p.keeper },
    { id: 'bw', role: 'bowler', x: 0.9 * off, y: L - 2.5 },
  ];
  p.f.forEach(([a, d], i) => fielders.push({ id: 'f' + i, x: off * d * Math.sin(a * rad), y: d * Math.cos(a * rad) }));
  fielders.forEach((f) => clampInside(f, L, boundary));
  return fielders;
}

/** Conventional name for a spot on the field. */
export function positionName(f, hand) {
  if (f.role === 'keeper') return 'Wicketkeeper';
  if (f.role === 'bowler') return 'Bowler';
  const off = hand === 'L' ? -1 : 1;
  const d = Math.hypot(f.x, f.y), a = Math.atan2(f.x * off, f.y) / rad, A = Math.abs(a), offSide = a >= 0;
  const close = d < 9, ring = d < 34;
  if (A >= 172) return close || d < 16 ? 'Short stop' : 'Long stop';
  if (offSide) {
    if (A < 30) return close ? 'Silly mid-off' : ring ? 'Mid-off' : 'Long-off';
    if (A < 50) return close ? 'Silly mid-off' : ring ? 'Extra cover' : 'Deep extra cover';
    if (A < 72) return close ? 'Silly point' : ring ? 'Cover' : 'Deep cover';
    if (A < 100) return close ? 'Silly point' : ring ? 'Point' : 'Deep point';
    if (A < 135) return d < 17 ? 'Gully' : ring ? 'Backward point' : 'Deep backward point';
    return d < 17 ? 'Slip' : ring ? 'Short third' : 'Third man';
  }
  if (A < 30) return close ? 'Silly mid-on' : ring ? 'Mid-on' : 'Long-on';
  if (A < 72) return close ? 'Short leg' : ring ? 'Midwicket' : 'Deep midwicket';
  if (A < 105) return close ? 'Short leg' : ring ? 'Square leg' : 'Deep square leg';
  if (A < 138) return d < 17 ? 'Leg gully' : ring ? 'Backward square leg' : 'Deep backward square';
  return d < 17 ? 'Leg slip' : ring ? 'Short fine leg' : 'Fine leg';
}

const css = (el, name) => getComputedStyle(el).getPropertyValue(name).trim();

/**
 * Top-down field view. Striker at the top, bowler below - the way you see it
 * from behind the bowler's arm, so a right-hander's off side is on the left.
 */
export class FieldView {
  constructor(canvas, state, onChange) {
    this.canvas = canvas; this.state = state; this.onChange = onChange;
    this.editable = false; this.shots = []; this.highlight = null; this.drag = null;
    canvas.addEventListener('pointerdown', (e) => this.down(e));
    canvas.addEventListener('pointermove', (e) => this.move(e));
    canvas.addEventListener('pointerup', () => this.up());
    canvas.addEventListener('pointercancel', () => this.up());
  }
  geom() {
    const r = this.canvas.getBoundingClientRect();
    const size = Math.min(r.width, r.height);
    const s = (size / 2 - 14) / this.state.boundary;
    return { r, s, cx: r.width / 2, cy: r.height / 2 };
  }
  toScreen(x, y, g) { return [g.cx - x * g.s, g.cy + (y - this.state.L / 2) * g.s]; }
  toWorld(px, py, g) { return [-(px - g.cx) / g.s, (py - g.cy) / g.s + this.state.L / 2]; }
  down(e) {
    if (!this.editable) return;
    const g = this.geom(), px = e.clientX - g.r.left, py = e.clientY - g.r.top;
    let best = null, bd = 26;
    for (const f of this.state.fielders) {
      const [sx, sy] = this.toScreen(f.x, f.y, g), d = Math.hypot(sx - px, sy - py);
      if (d < bd) { bd = d; best = f; }
    }
    if (best) { this.drag = best; this.canvas.setPointerCapture(e.pointerId); e.preventDefault(); this.draw(); }
  }
  move(e) {
    if (!this.drag) return;
    const g = this.geom();
    const [x, y] = this.toWorld(e.clientX - g.r.left, e.clientY - g.r.top, g);
    this.drag.x = x; this.drag.y = y;
    clampInside(this.drag, this.state.L, this.state.boundary);
    this.draw();
    this.onChange && this.onChange(this.drag, false);
  }
  up() { if (this.drag) { const f = this.drag; this.drag = null; this.draw(); this.onChange && this.onChange(f, true); } }

  draw() {
    const cv = this.canvas, g = this.geom(), dpr = window.devicePixelRatio || 1;
    if (!g.r.width) return;
    if (cv.width !== Math.round(g.r.width * dpr) || cv.height !== Math.round(g.r.height * dpr)) {
      cv.width = Math.round(g.r.width * dpr); cv.height = Math.round(g.r.height * dpr);
    }
    const c = cv.getContext('2d'), st = this.state, L = st.L;
    c.setTransform(dpr, 0, 0, dpr, 0, 0);
    c.clearRect(0, 0, g.r.width, g.r.height);
    const col = (n) => css(cv, n);
    // outfield + rope
    c.beginPath(); c.arc(g.cx, g.cy, st.boundary * g.s, 0, 7);
    c.fillStyle = col('--turf'); c.fill();
    c.lineWidth = 3; c.strokeStyle = col('--rope'); c.stroke();
    // 30-yard circle (two semicircles joined)
    const R30 = 27.43 * g.s, [ax, ay] = this.toScreen(0, 0, g), [, by] = this.toScreen(0, L, g);
    c.beginPath(); c.arc(ax, ay, R30, Math.PI, 0); c.lineTo(ax + R30, by); c.arc(ax, by, R30, 0, Math.PI); c.closePath();
    c.setLineDash([4, 5]); c.lineWidth = 1; c.strokeStyle = col('--ring'); c.stroke(); c.setLineDash([]);
    // pitch
    const pw = Math.max(5, 3.05 * g.s);
    c.fillStyle = col('--pitch'); c.fillRect(ax - pw / 2, ay - 1.5 * g.s, pw, (L + 3) * g.s);
    c.fillStyle = col('--chip-edge'); c.fillRect(ax - 3, ay - 1, 6, 2); c.fillRect(ax - 3, by - 1, 6, 2);
    // labels for orientation
    c.font = '500 11px Geist, system-ui, sans-serif'; c.fillStyle = col('--turf-ink'); c.textAlign = 'center';
    const offLeft = st.hand !== 'L';
    c.fillText(offLeft ? 'Off' : 'Leg', g.cx - st.boundary * g.s * 0.72, g.cy + 3);
    c.fillText(offLeft ? 'Leg' : 'Off', g.cx + st.boundary * g.s * 0.72, g.cy + 3);
    // earlier shots (wagon wheel)
    for (const sh of this.shots) {
      const hot = sh === this.highlight;
      if (hot) continue;
      this.path(c, g, sh, col, 0.35, 1.5);
    }
    if (this.highlight) this.path(c, g, this.highlight, col, 1, 3);
    // fielders
    for (const f of st.fielders) {
      const [sx, sy] = this.toScreen(f.x, f.y, g);
      const special = f.role === 'keeper' || f.role === 'bowler';
      const hit = this.highlight && this.highlight.by === f.id;
      c.beginPath(); c.arc(sx, sy, this.drag === f ? 10 : 7, 0, 7);
      c.fillStyle = hit ? col('--brass') : special ? col('--chip-edge') : col('--chip');
      c.fill(); c.lineWidth = 2; c.strokeStyle = col('--chip-edge'); c.stroke();
      if (this.editable || hit) {
        c.font = '500 11px Geist, system-ui, sans-serif'; c.fillStyle = col('--turf-ink'); c.textAlign = 'center';
        c.fillText(positionName(f, st.hand), sx, sy + (sy > g.cy + st.boundary * g.s * 0.8 ? -12 : 19));
      }
    }
  }
  path(c, g, sh, col, alpha, width) {
    if (!sh.path || sh.path.length < 2) return;
    c.globalAlpha = alpha;
    c.beginPath();
    sh.path.forEach((p, i) => { const [x, y] = this.toScreen(p[0], p[1], g); if (i) c.lineTo(x, y); else c.moveTo(x, y); });
    c.lineWidth = width; c.lineJoin = 'round';
    c.strokeStyle = sh.outcome === 'SIX' ? col('--six') : sh.outcome === 'FOUR' ? col('--four') : sh.outcome === 'CAUGHT' ? col('--out') : col('--run');
    c.stroke();
    const e = sh.path[sh.path.length - 1], [ex, ey] = this.toScreen(e[0], e[1], g);
    c.beginPath(); c.arc(ex, ey, width + 1.5, 0, 7); c.fillStyle = c.strokeStyle; c.fill();
    c.globalAlpha = 1;
  }
}

files.sim.js:
// Demo mode: a synthetic net session rendered through a virtual camera, so the
// whole pipeline (detection -> tracking -> 3D fit -> field outcome) can be tried
// without a camera. The generator is DOM-free so the tests can use it too.

import { G, RB, KD, CREASE, groundBounce } from './physics.js';
import { lookAtCam, project } from './geometry.js';

/** Generate one delivery with true physics (quadratic drag, small time step). */
export function generateDelivery(L, rnd = Math.random, o = {}) {
  const pick = (v, d) => (v === undefined ? d : v);
  const speed0 = pick(o.speed, 22 + rnd() * 18);
  const len = pick(o.length, 2.5 + rnd() * 6.5);
  const x0 = pick(o.x0, (0.45 + rnd() * 0.3) * (rnd() < 0.5 ? 1 : -1));
  const xT = pick(o.line, (rnd() - 0.5) * 0.5);
  const ax = pick(o.ax, (rnd() - 0.5) * 5);
  const turn = pick(o.turn, (rnd() - 0.5) * 6);
  const play = pick(o.play, rnd() < 0.82);
  const z0 = 2.05 + rnd() * 0.2, y0 = L - CREASE;
  const d = y0 - len, T = d / (0.95 * speed0);
  const vz = (RB - z0 + 0.5 * G * T * T) / T;
  const vx = (xT - x0 - 0.5 * ax * T * T) / T;
  const vy = -Math.sqrt(Math.max(1, speed0 * speed0 - vx * vx - vz * vz));
  const shotV = play ? (() => {
    const s = pick(o.shotSpeed, 12 + rnd() * 28);
    const az = pick(o.shotAz, (rnd() * 2 - 1) * 150) * Math.PI / 180;
    const el = pick(o.shotEl, -3 + rnd() * 38) * Math.PI / 180;
    return [s * Math.cos(el) * Math.sin(az), s * Math.cos(el) * Math.cos(az), s * Math.sin(el)];
  })() : null;
  const yHit = pick(o.yHit, 0.9 + rnd() * 0.9);

  const dt = 1 / 1200, pts = [];
  const p = [x0, y0, z0], v = [vx, vy, vz];
  const truth = { speed: Math.hypot(vx, vy, vz), ax, bounce: null, turnDeg: null, swingCm: null, shot: null };
  let hit = false, bounces = 0, tEnd = 0;
  for (let i = 0; i < 1200 * 3; i++) {
    pts.push(p[0], p[1], p[2]);
    const s = Math.hypot(v[0], v[1], v[2]);
    const sw = !hit && bounces === 0 ? ax : 0;
    v[0] += (sw - KD * s * v[0]) * dt; v[1] -= KD * s * v[1] * dt; v[2] -= (G + KD * s * v[2]) * dt;
    p[0] += v[0] * dt; p[1] += v[1] * dt; p[2] += v[2] * dt;
    tEnd = (i + 1) * dt;
    if (p[2] <= RB && v[2] < 0) {
      p[2] = RB;
      if (!hit && bounces === 0) {
        const h0 = Math.atan2(v[0], -v[1]);
        const h1 = h0 + turn * Math.PI / 180, sp = Math.hypot(v[0], v[1]) * 0.86;
        v[0] = sp * Math.sin(h1); v[1] = -sp * Math.cos(h1); v[2] = -0.55 * v[2];
        truth.bounce = { x: p[0], y: p[1], t: tEnd };
        truth.turnDeg = turn;
        truth.swingCm = 0.5 * ax * tEnd * tEnd * 100;
      } else groundBounce(v);
      bounces++;
    }
    if (!hit && shotV && p[1] <= yHit) {
      hit = true;
      if (!truth.bounce) truth.swingCm = 0.5 * ax * tEnd * tEnd * 100;
      truth.shot = {
        speed: Math.hypot(...shotV), impact: p.slice(), t: tEnd, v: shotV.slice(),
        elevDeg: Math.atan2(shotV[2], Math.hypot(shotV[0], shotV[1])) * 180 / Math.PI,
        azimDeg: Math.atan2(shotV[0], shotV[1]) * 180 / Math.PI,
      };
      v[0] = shotV[0]; v[1] = shotV[1]; v[2] = shotV[2];
    }
    if (!hit && p[1] < -8) break;                 // through to the keeper
    if (hit && tEnd > truth.shot.t + 1.6) break;
  }
  const posAt = (t) => {
    const i = Math.min(pts.length / 3 - 1, Math.max(0, Math.round(t / dt)));
    return [pts[3 * i], pts[3 * i + 1], pts[3 * i + 2]];
  };
  return { truth, tEnd, posAt };
}

/** A frame source that draws the synthetic scene to its own canvas. */
export class DemoSource {
  constructor(L, rectW) {
    this.kind = 'demo';
    this.L = L; this.rectW = rectW;
    this.width = 1280; this.height = 720;
    this.fps = 60;
    this.cam = lookAtCam([1.7, L + 7.5, 2.9], [0, 5, 0.6], 1150, this.width, this.height);
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.width; this.canvas.height = this.height;
    this.ctx = this.canvas.getContext('2d');
    this.time = 0; this.frame = 0;
    this.delivery = null; this.tStart = 0; this.nextAt = 1.0;
    this.lastTruth = null;
    this.running = false;
    this.seed = 12345;
  }
  rnd = () => {
    // mulberry32 so the demo is repeatable
    let t = (this.seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  /** Image positions of the calibration rectangle, in the order the app expects. */
  corners() {
    const hw = this.rectW / 2, L = this.L;
    const w = [[hw, 0, 0], [-hw, 0, 0], [-hw, L, 0], [hw, L, 0]].map((X) => project(this.cam, X));
    // order: striker-end left, striker-end right, bowler-end right, bowler-end left (as seen)
    const s = [w[0], w[1]].sort((a, b) => a[0] - b[0]);
    const b = [w[2], w[3]].sort((a, b) => a[0] - b[0]);
    return [s[0], s[1], b[1], b[0]].map((q) => [q[0] / this.width, q[1] / this.height]);
  }
  /** Image positions of the middle stump: striker base, striker top, bowler top, bowler base. */
  stumpPts() {
    const L = this.L;
    return [[0, 0, 0], [0, 0, 0.711], [0, L, 0.711], [0, L, 0]].map((X) => { const q = project(this.cam, X); return [q[0] / this.width, q[1] / this.height]; });
  }
  start(onFrame) {
    this.running = true;
    const tick = () => {
      if (!this.running) return;
      this.step();
      onFrame(this.time);
      this.raf = requestAnimationFrame(tick);
    };
    this.raf = requestAnimationFrame(tick);
  }
  stop() { this.running = false; cancelAnimationFrame(this.raf); }
  drawTo(ctx, w, h) { ctx.drawImage(this.canvas, 0, 0, w, h); }

  step() {
    this.time += 1 / this.fps; this.frame++;
    if (!this.delivery && this.time >= this.nextAt) {
      this.delivery = generateDelivery(this.L, this.rnd);
      this.tStart = this.time;
      this.lastTruth = this.delivery.truth;
    }
    if (this.delivery && this.time - this.tStart > this.delivery.tEnd) {
      this.delivery = null; this.nextAt = this.time + 2.6;
    }
    this.draw();
  }

  line(a, b, width, color) {
    const c = this.ctx, p = project(this.cam, a), q = project(this.cam, b);
    if (p[2] <= 0.1 || q[2] <= 0.1) return;
    c.strokeStyle = color; c.lineWidth = width; c.lineCap = 'round';
    c.beginPath(); c.moveTo(p[0], p[1]); c.lineTo(q[0], q[1]); c.stroke();
  }
  quad(pts, color) {
    const c = this.ctx;
    c.fillStyle = color; c.beginPath();
    pts.forEach((X, i) => { const p = project(this.cam, X); if (i) c.lineTo(p[0], p[1]); else c.moveTo(p[0], p[1]); });
    c.closePath(); c.fill();
  }
  draw() {
    const c = this.ctx, L = this.L, cam = this.cam, W = this.width, H = this.height;
    const hz = project(cam, [0, -400, 0])[1];
    const sky = c.createLinearGradient(0, 0, 0, hz);
    sky.addColorStop(0, '#8fb7d6'); sky.addColorStop(1, '#cfe1ea');
    c.fillStyle = sky; c.fillRect(0, 0, W, hz + 1);
    const grass = c.createLinearGradient(0, hz, 0, H);
    grass.addColorStop(0, '#4f8f47'); grass.addColorStop(1, '#2f6b33');
    c.fillStyle = grass; c.fillRect(0, hz, W, H - hz);
    this.quad([[1.525, -1.5, 0], [-1.525, -1.5, 0], [-1.525, L + 1.5, 0], [1.525, L + 1.5, 0]], '#c9b17c');
    const white = 'rgba(255,255,255,.9)';
    for (const y of [0, CREASE, L - CREASE, L]) this.line([-1.32, y, 0], [1.32, y, 0], 2, white);
    for (const x of [-1.32, 1.32]) { this.line([x, -0.3, 0], [x, CREASE, 0], 2, white); this.line([x, L - CREASE, 0], [x, L + 0.3, 0], 2, white); }
    for (const y of [0, L]) for (const x of [-0.1143, 0, 0.1143]) {
      const d = project(cam, [x, y, 0.35])[2];
      this.line([x, y, 0], [x, y, 0.711], Math.max(2, 0.038 * cam.f / d), '#efe3bd');
    }
    // Batter (right-handed, standing leg side of the stumps) with a bat that swings as the ball arrives.
    const d = this.delivery, tt = d ? this.time - this.tStart : -1;
    const dB = project(cam, [-0.45, 1.1, 0.9])[2], wB = 0.42 * cam.f / dB;
    this.line([-0.45, 1.1, 0.15], [-0.45, 1.1, 1.45], wB, '#20324a');
    this.line([-0.45, 1.1, 1.62], [-0.45, 1.1, 1.66], wB * 0.55, '#d8b48f');
    let sw = 0;
    if (d && d.truth.shot) sw = Math.min(1, Math.max(0, (tt - (d.truth.shot.t - 0.12)) / 0.2));
    const ang = -1.9 + sw * 3.0;
    this.line([-0.3, 1.1, 0.95], [-0.3 + 0.85 * Math.sin(ang) * 0.6, 1.1 + 0.4 * sw, 0.95 - 0.85 * Math.cos(ang)], Math.max(3, 0.1 * cam.f / dB), '#d9c08a');
    // Bowler running in and following through (a big moving shape the tracker must ignore).
    const run = d ? tt : (this.time - this.nextAt);
    if (run > -1.4 && run < 0.9) {
      const by = L + 1.5 - (run + 1.4) * 3.2, bx = -0.75;
      const db = project(cam, [bx, by, 0.9])[2];
      if (db > 0.5) {
        const wb = 0.42 * cam.f / db;
        this.line([bx, by, 0.15], [bx, by, 1.45], wb, '#f1efe6');
        this.line([bx, by, 1.62], [bx, by, 1.66], wb * 0.55, '#c99f7c');
      }
    }
    // Ball, drawn as a motion-blurred streak over the exposure time.
    if (d && tt >= 0) {
      const a = d.posAt(Math.max(0, tt - 0.5 / this.fps)), b = d.posAt(tt);
      const pa = project(cam, a), pb = project(cam, b);
      if (pb[2] > 0.3 && pa[2] > 0.3) {
        c.strokeStyle = '#b3161b'; c.lineCap = 'round';
        c.lineWidth = Math.max(2.2, 2 * RB * cam.f / pb[2]);
        c.beginPath(); c.moveTo(pa[0], pa[1]); c.lineTo(pb[0], pb[1]); c.stroke();
      }
    }
  }
}

